/* In-game "What's new" log. Newest first. `at` is the release time (Pacific). */
window.HW_DATA.support = { url: 'https://ko-fi.com/zerocrunchgames', qr: 'support-qr.png' };
window.HW_DATA.updates = [
  { v: '0.40', at: '2026-10-15 14:45', notes: ['Stone, clay and iron ore now run out. Each Boulder Field, Clay Bank and Iron Seam holds a deposit (about 60 stone, 60 clay or 30 ore); select one to see how much is left. Surface rocks still come back a few at a time until the deposit is used up.', 'Every tile you already own starts with a full deposit. When one is worked out you can change the land, buy from the market, survey new areas for fresh deposits, or unlock Deep Quarrying (after Prospecting) to reopen it.', 'Trees, ponds, flowers and reeds keep regrowing as before. Races and weekly challenges are unchanged.'] },
  { v: '0.39.3', at: '2026-10-15 13:20', notes: ['Balance: a station’s Quality upgrade now lifts goods one tier above their ingredients, never more. Basic logs make Good planks; Excellent goods need Good ingredients (well-watered or fertilized crops) plus the upgrade. Goods you already have keep their quality.', 'Master Crafting’s second Quality level now gives a bonus item on every third batch at that station instead.'] },
  { v: '0.39.2', at: '2026-10-15 08:20', notes: ['Repeat can now stop on its own: when Repeat is on, pick how many times (1 to 50, or Forever) from the box beside it. It shows how many are done and turns itself off at the end.', 'Four new Weekly Challenge themes join the rotation from next week: Barnyard Week (coop and dairy), Woolly Week (sheep and loom), Creamery Week (butter and cheese) and Helping Hands Week (a farmhand who runs errands). This week’s challenge is unchanged.'] },
  { v: '0.39.1', at: '2026-10-15 09:00', notes: ['Animal feed now always pays off: eggs, milk and wool are worth more than the crops they eat (milk is worth a little more, and carrot and vegetable feeds give more).', 'Orders no longer ask for Good-quality goods you can’t make yet (like Good logs or stone). They only ask for Good when your crops or a tuned station can make it.', 'You can now buy a Stove kit to build a second Stove once you have a second area.', 'Stations on Repeat now say when they use things up: Storage and the item card show “used automatically by …”, and the Activity log notes it once a day.'] },
  { v: '0.39', at: '2026-10-15 08:30', notes: ['Animals! Once you survey your first new area, a new Animals branch opens in Discovery: Chickens, Dairy Cows, Sheep and a Creamery. All peaceful.', 'Hens lay eggs and cows give milk when you feed them spare wheat or vegetables; sheep grow wool. Better feed makes better eggs, milk and wool.', 'New goods: omelettes and custard at the Stove, butter and cheese at the Creamery, Farmhouse Cake in the Oven, yarn and wool blankets at the Loom. Three new contracts to go with them.'] },
  { v: '0.38.1', at: '2026-10-15 07:50', notes: ['New-land contracts no longer hold you up: if the next contract needs an area you haven’t surveyed yet (like a Meadow for wildflowers), a contract for land you already have comes first, and the other waits until you survey its area.', 'Fixed: surveying a fourth area could ask for roof tiles before you owned Clay Banks to make them. Roof tiles are now only asked for once you have Clay Banks.'] },
  { v: '0.38', at: '2026-10-14 16:15', notes: ['Click any recipe at a station to see each ingredient: how many you have, how many you need, and what it costs at the market.', 'New Discovery: Errands (after Farmhand). From that recipe view, press Send farmhand shopping: your farmhand walks to the Open Market, buys what’s missing, brings it back and loads the station (one batch or fill every free slot), then goes back to their usual jobs.'] },
  { v: '0.37.2', at: '2026-10-14 15:50', notes: ['How quality works is now explained in the game: Storage → “How do I make Good and Excellent goods?”, a line on every farm plot and station (with “More about quality”), and on right-click item cards. Your first Basic harvest also gives a short tip.', 'In short: water a crop at both growth stages for Good, add fertilizer too for Excellent. Station goods are as good as their lowest ingredient, plus the station’s Quality upgrade.'] },
  { v: '0.37.1', at: '2026-10-14 15:10', notes: ['Right-click any item, recipe, kit or market row to see what it is: what it does, where it comes from, what it’s used to make and what it’s worth. Works in Storage, the market, stations and orders. On touch screens, press and hold.'] },
  { v: '0.37', at: '2026-10-14 14:05', notes: ['On a computer, the action menu now works like a window: drag its title bar to move it, drag any edge or corner to resize it, and it opens in that spot from then on. Double-click the title bar to send it back beside the tile you pick.', 'Weekly challenge runs are 10 minutes from next week (this week stays at 15 minutes, so everyone already on the board plays the same run).', 'The live count at the top right is now just the green dot and the number.'] },
  { v: '0.36.5', at: '2026-10-14 13:45', notes: ['On a computer, right-click the action menu and choose Move and resize: drag it anywhere, drag the corner to resize, then Done. It opens in that spot from then on. Right-click it again to go back to opening beside the tile.'] },
  { v: '0.36.4', at: '2026-10-14 13:30', notes: ['The action panel now sits a little further from the tile you pick, so it covers less of the buildings around it.'] },
  { v: '0.36.3', at: '2026-10-14 13:40', notes: ['On computers and tablets, the action panel now opens beside the tile you pick and follows it as you move the view (phones keep the panel at the bottom).', 'Every action you can take now has a gold border, so no single option looks like the only one. Greyed-out actions still say what they need.'] },
  { v: '0.36.2', at: '2026-10-14 13:30', notes: ['A live count at the top right shows how many copies of Harvest Valley are open right now, updated every 30 seconds.'] },
  { v: '0.36.1', at: '2026-10-14 09:40', notes: ['Your player name now lives with you, not a farm: set it on the Weekly challenge screen or in Settings → Your player name (private farms too). It shows on the leaderboard, the weekly board and your medals instead of “Farmer”.'] },
  { v: '0.36', at: '2026-10-14 01:30', notes: ['New: the Weekly Challenge (main menu). Everyone gets the same head start for the week, with a new theme each week: Bumper Crop, Baker’s, Fisher’s, Timber, Quarry and more, each with its own starting buildings, land and score bonus.', 'One ranked 15-minute run a day; your best run of the week counts. Extra runs are practice. The top three each week win a gold, silver or bronze medal.', 'Medals live in Menu → Medals and can be put on show on any of your farms. Select a medal on your farm to see when you won it.', 'New: a player key (Menu → Player key). One code that carries your locked name, your medals and your backed-up farms to another phone or computer. Restoring a farm now lets you pick which of your three slots it goes into.'] },
  { v: '0.35.1', at: '2026-10-13 23:40', notes: ['The game is now called Harvest Valley, with new title art. Your farms, saves and backup codes carry on as before.'] },
  { v: '0.35', at: '2026-10-13 23:20', notes: ['Three ways to play from the main menu: Online Valley (shared market prices, the ticker and the leaderboard), Private farm (just you, on your own time) and Race.', 'Your existing farms are Online Valley farms. Settings → This farm can make a farm private (one way only).'] },
  { v: '0.34.1', at: '2026-10-13 23:10', notes: ['Buying land (and surveying new areas) now lists everything it costs, not just the gold, with how much of each you have and how many more you need.'] },
  { v: '0.34', at: '2026-10-13 23:00', notes: ['Open Market → Stations now shows only what you can build. Stations you’ve reached your limit on have their own “At your limit” list.', 'New Farmhands menu (Menu, the Jobs button on the farmhand bar, or the Homestead): pause, set speed, and reorder, remove or clear jobs in one place.'] },
  { v: '0.33.1', at: '2026-10-13 22:40', notes: ['Every race now starts differently: gold, land, stations, plots, seeds and even spare Discovery are shuffled, but everyone in the same race gets the identical head start, and it’s always winnable.', 'Watch out for greed traps: a race-day bargain on a station you can’t actually use, and a rich-looking special request that pays gold but hardly any points.'] },
  { v: '0.33', at: '2026-10-13 22:30', notes: ['Save slots: keep up to three farms side by side. Main menu → Your farms (or Menu → Your farms) to switch farms or start a new one.', 'Race with friends: host a race to 500, 1,000, 2,500 or 5,000 points and share the code or invite link. Everyone starts the same head-start farm in its own slot, so your real farm is safe. A live race bar shows everyone’s progress, and first to the target wins. No pausing during a race, and races don’t affect valley prices or the leaderboard.'] },
  { v: '0.32.1', at: '2026-10-13 22:00', notes: ['Idle pause now offers Never, 5, 10, 15 or 30 seconds, or 2 minutes (Settings → Pausing). It starts at 2 minutes.'] },
  { v: '0.32', at: '2026-10-13 21:55', notes: ['The game now pauses itself if you haven’t done anything for a while (10 minutes to start). Pick Never, 2, 5, 10 or 30 minutes in Settings → Pausing. Any tap, click or key carries on.', 'Menu → Cloud backup has a clear Copy code button next to your backup code.'] },
  { v: '0.31.1', at: '2026-10-13 21:45', notes: ['The Open Market’s Buy tab now warns you when storage is full (or nearly full), before you try to buy.'] },
  { v: '0.31', at: '2026-10-13 21:40', notes: ['Cloud backup: Menu → Cloud backup saves your farm to the valley and gives you a 12-letter code. On any phone or computer, choose Restore from a backup code on the main menu to get your farm back. It backs up on its own every 10 minutes or so while you play.', 'On phones, Share save file opens your phone’s share sheet so you can save the file to Files, AirDrop it or email it.'] },
  { v: '0.30.1', at: '2026-10-13 15:30', notes: ['Settings → Leaderboard name: lock in a name that’s yours alone across the valley. If it’s taken you’ll be offered the next free number, like Zac1. Locked names show a ✓ on the leaderboard.'] },
  { v: '0.30', at: '2026-10-13 15:15', notes: ['Valley leaderboard: see how your farm compares with everyone else’s, by top score and by best pace (score per day played, for farms at least 7 days old). Open it from the Menu or from your weekly report.', 'Your farmer’s name is shown by default; turn that off in Settings to appear as “A farmer”. The leaderboard works on the web version.'] },
  { v: '0.29', at: '2026-10-13 15:00', notes: ['Every 7 days a weekly report shows how your farm did: gold, score, Discovery, sales, harvests, orders and what you made. Turn it off from the report or in Settings.', 'Settings now has its own page in the Menu, with Pausing, Notifications and Sound.'] },
  { v: '0.28', at: '2026-10-13 14:45', notes: ['Hit rock bottom (no gold for seeds, nothing to sell, nothing growing and no work that brings in goods) and the valley bank lends you 100g, once. Pay it back: it comes out automatically at 200g, or tap Loan in the top bar.', 'Get stuck again before repaying it, and that farm is over: start a new one or take one last look around.'] },
  { v: '0.27.3', at: '2026-10-13 14:30', notes: ['On computers, the valley market ticker now stretches across the full width of the screen.'] },
  { v: '0.27.2', at: '2026-10-13 14:20', notes: ['Discovery, Storage and the Market remember the category tab you last picked, even after you reload the game.'] },
  { v: '0.27.1', at: '2026-10-13 14:10', notes: ['On computers, the valley market ticker now runs along its own row under your gold and storage, so it’s easier to read.'] },
  { v: '0.27', at: '2026-10-13 14:00', notes: ['Harvestworks has sound! Gentle chimes when crops ripen, stations finish and contracts complete, soft sounds for chopping, mining, fishing, watering and selling, plus a breeze, birds by day and crickets at dusk.', 'Optional calm background music that never repeats itself.', 'Menu → Sound: turn sound on or off, and set Effects, Ambience and Music volumes. Press M to mute quickly.'] },
  { v: '0.26', at: '2026-10-13 13:45', notes: ['New in Menu → Options: choose whether the game pauses when you switch to another tab or app. Turn pausing off and your farm keeps working while you’re away (up to 2 hours), catching up when you come back.'] },
  { v: '0.25', at: '2026-10-13 13:30', notes: ['New lands: unlock Land Surveying in Discovery, then select a dashed area past your map’s edge to survey it. Each area is a Meadow, Clay Banks, Marsh or Iron Hills, and every survey costs more than the last.', 'New resources in those areas: wildflowers, clay, reeds and iron ore, with new things to make: Wildflower Honey, Dye and Dyed Cloth (Dye Vat), Roof Tiles and Clay Pots (Potter’s Wheel), Baskets, and Iron Ingots and Iron Tools (Forge). Five new contracts use them.', 'Building limits: you can build one of each station per area you own, and two Storage Barns. Buildings you already have stay. Surveying new land raises the limit.', 'Rollers & Skids (Discovery): move a station, storage building or sprinkler to a new spot, upgrades and all. It’s pricey, and each move costs more for a few days.'] },
  { v: '0.24', at: '2026-10-13 11:45', notes: ['New title art on the welcome screen and main menu.'] },
  { v: '0.23.1', at: '2026-10-13 11:30', notes: ['Fixed: the “new version” banner could keep asking you to reload without actually loading the update. Reload now always brings in the latest version, and Later stops it asking again for that update.', 'The banner can now be reached from the title screen too.'] },
  { v: '0.23', at: '2026-10-13 11:15', notes: ['Buildings no longer fade when they’re in front of things; the shorter buildings keep the view clear.', 'The eye button (or X) now shows the name of every building on your farm.'] },
  { v: '0.22', at: '2026-10-13 11:00', notes: ['Buildings are about 25% shorter, so a busy farm is easier to see across. Each one keeps its look: chimneys, sails, awnings and all.', 'Busy farms are easier to read.'] },
  { v: '0.21', at: '2026-10-13 10:45', notes: ['Buildings, trees and rocks now fade when they stand in front of your farmer, your farmhand, the tile you’ve selected or the tile under your mouse, so nothing gets lost behind them.'] },
  { v: '0.20.2', backend: true, at: '2026-10-13 10:30', notes: ['Show your support now points to Ko-fi (ko-fi.com/zerocrunchgames) instead of PayPal, with a new QR code.'] },
  { v: '0.20.1', backend: true, at: '2026-10-13 10:20', notes: ['Name back to Harvestworks. Show your support opens its own screen with a big QR code and an Open PayPal link (title menu and Menu).'] },
  { v: '0.20', at: '2026-10-13 10:10', notes: ['New title screen and main menu: Continue, New farm (name your farmer) and Load a save file.', 'New players can take a quick hands-on tutorial; replay it any time from the Menu.'] },
  { v: '0.19.1', at: '2026-10-13 00:20', notes: ['Open Market → Buy has category filters, the same as Sell.'] },
  { v: '0.19', at: '2026-10-13 00:15', notes: ['Open Market → Buy now sells every good you’ve made at least once (apples, bread, cider and the rest), at about 1.75× its normal value, Normal quality.', 'On the web version, buying pushes that good’s shared price up and selling pushes it down, for everyone.'] },
  { v: '0.18.1', at: '2026-10-13 00:05', notes: ['Fixed: choosing a save file in Menu → Load a save file did nothing. You now get a “Reading…” note, then a “Load this farm” button (or a clear error if the file isn’t a save).'] },
  { v: '0.18', at: '2026-10-12 23:42', notes: ['Menu → Download save file saves your whole farm as a .json file; Load a save file brings it back on any device or on the web version.', 'Save codes are still there under “Or copy and paste a save code instead”.'] },
  { v: '0.17', at: '2026-10-12 23:40', notes: ['Move your farm: Menu → Export save code gives you a code to copy; Menu → Import a save code on another device or on the web version brings the whole farm across.'] },
  { v: '0.16', at: '2026-10-12 23:28', notes: ['The valley market now moves at the pace of the crowd: with only a couple of traders, prices take about a day to settle back; with dozens or hundreds, they settle in minutes and each sale has a smaller effect.', 'The market shows how many traders are active this hour and how long prices take to settle.'] },
  { v: '0.15', at: '2026-10-12 23:20', notes: ['Shared valley market: on the web version, every player’s sales and purchases move prices for everyone. Prices drift back to normal over a few hours, between half and 1.6× of normal.', 'The market shows each price’s movement (▲/▼) and whether shared prices are connected.', 'Valley market ticker in the top bar shows recent trades. Collapse it with –, and switch between Slow and Fast.'] },
  { v: '0.14', at: '2026-10-12 23:02', notes: ['Activity log: a list of everything you and your farmhand have done. Open it with the Activity button at the bottom left.', 'Updates log (this list): opens by itself after each update so you can see what changed.'] },
  { v: '0.13', at: '2026-10-12 22:58', notes: ['Fertilized crops grow 40% faster as well as gaining +1 quality.'] },
  { v: '0.12', at: '2026-10-12 22:56', notes: ['Add fertilizer to a crop that’s already growing.'] },
  { v: '0.11', at: '2026-10-12 22:54', notes: ['Sell seeds, seedlings, saplings and fertilizer at the market (half price).', 'Storage and the market explain how to use seeds, saplings, fertilizer and kits.', 'Apple Seedling renamed Apple Tree Seedling.'] },
  { v: '0.10.1', at: '2026-10-12 22:50', notes: ['No more blue flash when tapping the map on phones.'] },
  { v: '0.10', at: '2026-10-12 22:47', notes: ['The contract card lists what you need with have/need counts.', '“See everything it takes” shows a production tree back to raw materials.'] },
  { v: '0.9', at: '2026-10-12 22:42', notes: ['Clear all of the farmhand’s jobs from the status chip or the Homestead.'] },
  { v: '0.8.1', at: '2026-10-12 22:40', notes: ['Upgrade costs wrap instead of hiding under the button.'] },
  { v: '0.8', at: '2026-10-12 22:38', notes: ['Every station’s Capacity upgrades to 12 slots and Speed to ×5.0.', '“Fill ×N” loads as many batches as you can in one trip.'] },
  { v: '0.7', at: '2026-10-12 22:35', notes: ['Farmhand play/pause and speed (1×/2×/3×) buttons.'] },
  { v: '0.6', at: '2026-10-12 11:02', notes: ['Change this land: clear forest, boulders or ponds, or make woodland, ponds and rock fields.', 'A minimized contract sits in the top bar.'] },
  { v: '0.5', at: '2026-10-12 10:58', notes: ['Minimize the goal/contract card.'] },
  { v: '0.4', at: '2026-10-12 10:41', notes: ['Phone layout and touch controls (twist to turn, two-finger slide to tilt).'] },
  { v: '0.3', at: '2026-10-11 23:11', notes: ['Upgrade rows show their cost and what you’re short of.'] },
  { v: '0.2', at: '2026-10-11 22:58', notes: ['Storage keeps growing: Homestead levels past 220, Storage Barns and Warehouses.'] },
  { v: '0.1', at: '2026-10-11 22:49', notes: ['First public build.'] }
];
